    int a[] = { 1, 12, 15, 26, 38 };
    int b[] = { 2, 13, 17, 30, 45 };

    int size1 = sizeof(a) / sizeof(a[0]);
    int size2 = sizeof(b) / sizeof(b[0]);

    printf("%f", getMedian(a, size1, b, size2));

